export const structures = {};

function add(id, name, parent, group, level, model, data) {
  structures[id] = {
    id, name, synonyms: [], parent, group, level, scale: 'Schéma pédagogique, proportions non métriques.', model,
    location: '', composition: '', cells: '', functions: '', relations: '', origin: '', trap: '',
    pages: [], supplement: '', references: [], ...data,
  };
  if (structures[id].pages.length && !structures[id].references.includes('tn1')) structures[id].references.unshift('tn1');
}

